-- =============================================================================
-- Migration 010 — Comarca polygon geometry (PostGIS MultiPolygon, SRID 4326)
-- =============================================================================
-- Adds polygon column on public.comarques and populates real boundaries for
-- all 41 Catalan comarques. Used by /cop frontend choropleth.
--
-- Source: aariste/GeoJSON-Mapas (simplified comarques-compressed.geojson)
--   https://github.com/aariste/GeoJSON-Mapas/blob/master/comarques-compressed.geojson
-- Upstream provenance: ICGC (Institut Cartogràfic i Geològic de Catalunya)
--   https://www.icgc.cat/Descarregues/Cartografia-i-mapes/Mapes-administratius
--
-- Coordinates rounded to 5 decimals (~1.1m) — sufficient for comarca-scale choropleth.
-- Total ~5,300 vertices across 41 comarques. Wraps each Polygon list in MultiPolygon
-- so all rows have a uniform geometry type (some comarques have islands / exclaves).
--
-- Slug 'gironeso' is intentionally duplicated alongside 'girones' to cover the
-- legacy typo present in earlier seeds. The `WHERE slug = ...` clause makes any
-- non-matching row a silent no-op, so unknown comarques are harmless.
-- =============================================================================

BEGIN;

-- Requires PostGIS (Supabase enables this by default; otherwise run once: CREATE EXTENSION postgis;).
ALTER TABLE public.comarques
  ADD COLUMN IF NOT EXISTS polygon geometry(MultiPolygon, 4326);

CREATE INDEX IF NOT EXISTS comarques_polygon_gist
  ON public.comarques USING gist(polygon);

-- ---------------------------------------------------------------------------
-- Polygon UPSERTs — one UPDATE per comarca slug.
-- ---------------------------------------------------------------------------

